from pathlib import Path
import json,gzip,hashlib,re
root=Path('/home/osso/.worktrees/wow-ui-sim-p335-source')
here=root/'data/patch-api/evidence/3.3.5-session-2026-10-09'
sha=lambda b:hashlib.sha256(b).hexdigest()
manifest=json.loads((here/'historical-inputs.json').read_bytes())
bundle=json.loads(gzip.decompress((here/'historical-bundle.json.gz').read_bytes()))
sealed={}
for p,v in manifest['sealed_files'].items():
 b=(root/p).read_bytes(); assert sha(b)==v['sha256'] and len(b)==v['bytes'],p
 sealed[p]={'sha256':sha(b),'bytes':len(b)}
assert len(sealed)==25 and len(bundle)==77 and len(manifest['later_registers'])==68
archive={}
for p,text in bundle.items():
 b=text.encode(); assert sha(b)==manifest['snapshot_sha256'][p],p
 archive[p]={'sha256':sha(b),'bytes':len(b),'current_equal':(root/p).exists() and (root/p).read_bytes()==b}
preserved={}
for p,v in json.loads((here/'original-output-hashes.json').read_bytes()).items():
 b=(root/p).read_bytes(); assert sha(b)==v['sha256'] and len(b)==v['bytes'],p
 preserved[p]={'sha256':sha(b),'bytes':len(b)}
assert len(preserved)==149
own=json.loads((root/'data/patch-api/sources/3.3.5-wikitext-register.json').read_bytes())
assert own['client_line']=='retail' and len(own['entries'])==124
sweep=(root/'tests/patch_3_3_5_publication_sweep.rs').read_text()
paths=re.findall(r'include_str!\("\.\./(data/patch-api/sources/[^\"]+-wikitext-register.json)"\)',sweep)
assert paths[0]=='data/patch-api/sources/3.3.5-wikitext-register.json'
paths=paths[1:]
assert paths==['data/patch-api/sources/4.0.1-wikitext-register.json']+manifest['later_registers']
actual=[]
for p in paths:
 b=(root/p).read_bytes(); register=json.loads(b)
 assert register.get('client_line','retail')=='retail',p
 assert tuple(map(int,register['patch'].split('.'))) >= (4,0,1),p
 if p in manifest['later_registers']: assert b==bundle[p].encode(),p
 actual.append({'path':p,'patch':register['patch'],'client_line':register.get('client_line','retail'),'entries':len(register['entries']),'sha256':sha(b)})
added=json.loads((root/paths[0]).read_bytes())
keys=lambda register:{(e['section'],e['symbol']) for e in register['entries']}
symbols=lambda register:{e['symbol'] for e in register['entries']}
pairs=keys(own)&keys(added); names=symbols(own)&symbols(added)
assert not pairs and not names
# Rust later_publication keys symbols, not sections, ignores changed rows, and applies input order.
def expected(later):
 latest={}
 for register in later:
  for e in register['entries']:
   if e['direction']!='changed':latest[e['symbol']]=e
 result={}
 for e in own['entries']:
  newer=latest.get(e['symbol']); own_removed=e['direction']=='removed'
  removed=newer['direction']=='removed' if newer else own_removed
  result[e['id']]={'symbol':e['symbol'],'section':e['section'],'publication':'absent' if removed else 'published','superseded_by':newer['id'] if newer and removed!=own_removed else None}
 return result
historical=expected([json.loads(bundle[p]) for p in manifest['later_registers']])
current=expected([json.loads((root/p).read_bytes()) for p in paths])
assert historical==current
original=json.loads((here/'own-sweep-green-results.json').read_bytes())
assert all(original[k]['expected']==v for k,v in historical.items())
assert sum(v['ok'] for v in original.values())==80 and sum(not v['ok'] for v in original.values())==44
historical_logs=[]
for command in json.loads((here/'command-ledger.json').read_bytes())['commands']:
 b=(here/command['artifact']).read_bytes()
 historical_logs.append({'command':command,'log':b.decode(),'log_sha256':sha(b),'log_bytes':len(b)})
proof=json.loads((here/'validator-development-proof.json').read_bytes())
for path,key in [('validate.py','validator_sha256'),('validator-green.log','log_sha256')]:
 assert sha((here/path).read_bytes())==proof[key]
assert sha((root/'tools/test_patch_3_3_5_validator.py').read_bytes())==proof['fixture_sha256']
assert sha((here/'historical-inputs.json').read_bytes())==proof['historical_manifest_sha256']
result={'sealed_files':sealed,'archive_files':archive,'original_outputs':preserved,'actual_successors':actual,'successors_current':len(actual),'original_successors':68,'new_4_0_1_rows':len(added['entries']),'new_4_0_1_section_symbol_overlap':sorted(pairs),'new_4_0_1_symbol_overlap':sorted(names),'all_124_expectations_unchanged':True,'original_observed_ok':80,'original_observed_gaps':44,'historical_logs':historical_logs,'validator_green_receipt':proof,'validator_green_log':(here/'validator-green.log').read_text(),'manifest_sha256':sha((here/'historical-inputs.json').read_bytes()),'bundle_sha256':sha((here/'historical-bundle.json.gz').read_bytes())}
print(json.dumps(result,indent=2,sort_keys=True))

